using Microsoft.Dynamics.AX.Security.Management.Domain;
using Microsoft.Dynamics.AX.Security.Management.Domain.Privilege;
using Niedax.AX.Security;

/// <summary>
/// PaffH 11.01.21
/// </summary>
public class NDXPrivilegeTable extends common
{

}

Method.Source:
/// <summary>
/// PaffH 11.01.21
/// </summary>
/// <param name = "_PrivilegeIdentifier">NDXPrivilegeIdentifier</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXPrivilegeTable</returns>
static public NDXPrivilegeTable find(NDXPrivilegeIdentifier _PrivilegeIdentifier,
                              boolean _forUpdate = false)
{
    NDXPrivilegeTable   nDXPrivilegeTable;

    nDXPrivilegeTable.selectForUpdate(_forUpdate);

    select firstonly nDXPrivilegeTable
        where nDXPrivilegeTable.PrivilegeIdentifier == _PrivilegeIdentifier;

    return nDXPrivilegeTable;
}

/// <summary>
/// PaffH 11.01.21
/// </summary>
/// <param name = "_PrivilegeIdentifier">NDXPrivilegeIdentifier</param>
/// <param name = "_doInsert">boolean</param>
/// <returns>NDXPrivilegeTable</returns>
static NDXPrivilegeTable findOrCreate(NDXPrivilegeIdentifier _PrivilegeIdentifier, boolean _doInsert = true)
{
    NDXPrivilegeTable   nDXPrivilegeTable = NDXPrivilegeTable::find(_PrivilegeIdentifier, true);
    if (!nDXPrivilegeTable)
    {
        nDXPrivilegeTable.PrivilegeIdentifier = _PrivilegeIdentifier;
        if (_doInsert)
        {
            nDXPrivilegeTable.insert();
        }
    }
    return nDXPrivilegeTable;
}

/// <summary>
/// PaffH 19.01.21
/// save from Privilege
/// </summary>
/// <param name = "_Privilege">Privilege</param>
/// <param name = "updatedUtcDateTime">NDXUpdatedUTCDateTime</param>
/// <param name = "doSave">boolean</param>
/// <returns>NDXPrivilegeTable</returns>
static NDXPrivilegeTable saveFromPrivilege(Privilege _Privilege, NDXUpdatedUTCDateTime updatedUtcDateTime, boolean doSave = true)
{
    NDXPrivilegeTable nDXPrivilegeTable;
    nDXPrivilegeTable = NDXPrivilegeTable::findOrCreate(_Privilege.Identifier, false);
    nDXPrivilegeTable.Name = _Privilege.Name;
    nDXPrivilegeTable.Description = _Privilege.Description;
    nDXPrivilegeTable.UpdatedUTCDateTime = updatedUtcDateTime;
    if (doSave && nDXPrivilegeTable.ValidateWrite())
    {
        ttsbegin;
        nDXPrivilegeTable.write();
        ttscommit;
    }
    return nDXPrivilegeTable;
}

/// <summary>
/// PaffH 19.01.21
/// save from NDXPrivilege
/// </summary>
/// <param name = "_NDXPrivilege">NDXPrivilege</param>
/// <param name = "updatedUtcDateTime">NDXUpdatedUTCDateTime</param>
/// <param name = "isReferencedInRole">NDXIsReferencedInRole</param>
/// <returns>NDXPrivilegeTable</returns>
static NDXPrivilegeTable saveFromNDXPrivilege(NDXPrivilege _NDXPrivilege, NDXUpdatedUTCDateTime updatedUtcDateTime, NDXIsReferencedInRole isReferencedInRole = NoYes::No)
{
    NDXPrivilegeTable nDXPrivilegeTable;
    nDXPrivilegeTable = NDXPrivilegeTable::saveFromPrivilege(_NDXPrivilege.Privilege, updatedUtcDateTime, false);
    nDXPrivilegeTable.LicenseTypeFinancial = _NDXPrivilege.LicenseTypeFinancial;
    nDXPrivilegeTable.IsReferencedInRole = isReferencedInRole;
    if (nDXPrivilegeTable.ValidateWrite())
    {
        ttsbegin;
        nDXPrivilegeTable.write();
        ttscommit;
    }
    return nDXPrivilegeTable;
}

/// <summary>
/// PaffH 20.01.21
/// delete records not updated
/// </summary>
/// <param name = "_updatedUtcDateTime">NDXUpdatedUTCDateTime</param>
/// <param name = "_logger">NDXLoggerSecurityInformationClass</param>
/// <returns>counter deleted records</returns>
static public int deleteNotUpdated(NDXUpdatedUTCDateTime _updatedUtcDateTime, NDXLoggerSecurityInformationClass _logger)
{
    NDXPrivilegeTable nDXPrivilegeTable;
    NDXArgsLoggerSecuritiyInformation argsLogger = new NDXArgsLoggerSecuritiyInformation();
    argsLogger.parmLogActivity(strFmt("@NDX:NDXDeleteRecordsInTable", tableId2PName(nDXPrivilegeTable.TableId)));
    _logger.LogLineCreate(argsLogger);

    NDXHelperTable::skipForDelete(nDXPrivilegeTable);
    delete_from nDXPrivilegeTable
        where nDXPrivilegeTable.UpdatedUTCDateTime != _updatedUtcDateTime;

    argsLogger.parmCounter(int642int(nDXPrivilegeTable.RowCount()));
    _logger.LogLineChange(argsLogger);

    return int642int(nDXPrivilegeTable.RowCount());
}
